83	// Keep track of workspace libs we already read package.json for so we don't read from disk again.
84	const seenWorkspaceDeps: Record<string, { name: string; version: string }> = {};
85	
86	function collectDependenciesFromFileMap(
87	  workspaceRoot: string,
88	  sourceProject: ProjectGraphProjectNode,
89	  projectGraph: ProjectGraph,
90	  projectFileMap: ProjectFileMap,
91	  buildTarget: string,
92	  ignoredFiles: string[],
93	  useLocalPathsForWorkspaceDependencies: boolean,
94	  npmDeps: Record<string, string>
95	): void {
96	  const rawFiles = projectFileMap[sourceProject.name];
97	  if (!rawFiles) return;
98	
99	  // If build target does not exist in project, use all files as input.
100	  // This is needed for transitive dependencies for apps -- where libs may not be buildable.
101	  const inputs = sourceProject.data.targets[buildTarget]
102	    ? getTargetInputs(readNxJson(), sourceProject, buildTarget).selfInputs
103	    : ['{projectRoot}/**/*'];
104	  if (ignoredFiles) {
105	    for (const pattern of ignoredFiles) {
106	      inputs.push(`!${pattern}`);
107	    }
108	  }
109	  const files = filterUsingGlobPatterns(
110	    sourceProject.data.root,
111	    projectFileMap[sourceProject.name] || [],
112	    inputs
113	  );
114	
115	  for (const fileData of files) {
116	    if (
117	      !fileData.deps ||
118	      fileData.file ===
119	        joinPathFragments(sourceProject.data.root, 'package.json')
120	    ) {
121	      continue;
122	    }
123	
124	    for (const dep of fileData.deps) {
125	      const target = fileDataDepTarget(dep);
126	
127	      // If the node is external, then read package info from `data`.
128	      const externalDep = projectGraph.externalNodes[target];
129	      if (externalDep?.type === 'npm') {
130	        npmDeps[externalDep.data.packageName] = externalDep.data.version;
131	        continue;
132	      }
133	
134	      // If node is internal, then try reading package info from `package.json` (which must exist for this to work).
135	      const workspaceDep = projectGraph.nodes[target];
136	      if (!workspaceDep) continue;
137	      const cached = seenWorkspaceDeps[workspaceDep.name];
138	      if (cached) {
139	        npmDeps[cached.name] = cached.version;
140	      } else {
141	        const packageJson = readPackageJson(workspaceDep, workspaceRoot);
142	        if (
143	          // Check that this is a buildable project, otherwise it cannot be a dependency in package.json.
144	          workspaceDep.data.targets[buildTarget] &&
145	          // Make sure package.json exists and has a valid name.
146	          packageJson?.name
147	        ) {
148	          let version: string;
149	          if (useLocalPathsForWorkspaceDependencies) {
150	            // Find the relative `file:...` path and use that as the version value.
151	            // This is useful for monorepos like Nx where the release will handle setting the correct version in dist.
152	            const depRoot = join(workspaceRoot, workspaceDep.data.root);
153	            const ownRoot = join(workspaceRoot, sourceProject.data.root);
154	            const relativePath = relative(ownRoot, depRoot);
155	            const filePath = normalizePath(relativePath); // normalize slashes for windows
156	            version = `file:${filePath}`;
157	          } else {
158	            // Otherwise, read the version from the dependencies `package.json` file.
159	            // This is useful for monorepos that commit release versions.
160	            // Users can also set version as "*" in source `package.json` files, which will be the value set here.
161	            // This is useful if they use custom scripts to update them in dist.
162	            version = packageJson.version ?? '*'; // fallback in case version is missing
163	          }
164	          npmDeps[packageJson.name] = version;
165	          seenWorkspaceDeps[workspaceDep.name] = {
166	            name: packageJson.name,
167	            version,
168	          };
169	        }
170	      }
171	    }
172	  }
173	}
