175	function readPackageJson(
176	  project: ProjectGraphProjectNode,
177	  workspaceRoot: string
178	): null | {
179	  name: string;
180	  version?: string;
181	  dependencies?: Record<string, string>;
182	  optionalDependencies?: Record<string, string>;
183	  peerDependencies?: Record<string, string>;
184	} {
185	  const packageJsonPath = join(
186	    workspaceRoot,
187	    project.data.root,
188	    'package.json'
189	  );
190	  if (fileExists(packageJsonPath)) return readJsonFile(packageJsonPath);
191	  return null;
192	}
