1	import { offsetFromRoot, Tree, updateJson, workspaceRoot } from '@nx/devkit';
2	import { existsSync, readFileSync } from 'fs';
3	import { dirname, isAbsolute, join, resolve } from 'path';
4	import type * as ts from 'typescript';
5	import { ensureTypescript } from './ensure-typescript';
6	
7	let tsModule: typeof import('typescript');
8	
9	export function readTsConfig(
10	  tsConfigPath: string,
11	  sys?: ts.System
12	): ts.ParsedCommandLine {
13	  if (!tsModule) {
14	    tsModule = require('typescript');
15	  }
16	
17	  sys ??= tsModule.sys;
18	
19	  const readResult = tsModule.readConfigFile(tsConfigPath, sys.readFile);
20	  return tsModule.parseJsonConfigFileContent(
21	    readResult.config,
22	    sys,
23	    dirname(tsConfigPath)
24	  );
25	}
26	
27	export function readTsConfigFromTree(
28	  tree: Tree,
29	  tsConfigPath: string
30	): ts.ParsedCommandLine {
31	  if (!tsModule) {
32	    tsModule = ensureTypescript();
33	  }
34	
35	  const tsSysFromTree: ts.System = {
36	    ...tsModule.sys,
37	    readFile: (path) => tree.read(path, 'utf-8'),
38	  };
39	
40	  return readTsConfig(tsConfigPath, tsSysFromTree);
41	}
