43	export function getRootTsConfigPathInTree(tree: Tree): string | null {
44	  for (const path of ['tsconfig.base.json', 'tsconfig.json']) {
45	    if (tree.exists(path)) {
46	      return path;
47	    }
48	  }
49	
50	  return 'tsconfig.base.json';
51	}
52	
53	export function getRelativePathToRootTsConfig(
54	  tree: Tree,
55	  targetPath: string
56	): string {
57	  return offsetFromRoot(targetPath) + getRootTsConfigPathInTree(tree);
58	}
