60	export function getRootTsConfigPath(): string | null {
61	  const tsConfigFileName = getRootTsConfigFileName();
62	
63	  return tsConfigFileName ? join(workspaceRoot, tsConfigFileName) : null;
64	}
65	
66	export function getRootTsConfigFileName(tree?: Tree): string | null {
67	  for (const tsConfigName of ['tsconfig.base.json', 'tsconfig.json']) {
68	    const pathExists = tree
69	      ? tree.exists(tsConfigName)
70	      : existsSync(join(workspaceRoot, tsConfigName));
71	
72	    if (pathExists) {
73	      return tsConfigName;
74	    }
75	  }
76	
77	  return null;
78	}
