80	export function addTsConfigPath(
81	  tree: Tree,
82	  importPath: string,
83	  lookupPaths: string[]
84	) {
85	  updateJson(tree, getRootTsConfigPathInTree(tree), (json) => {
86	    json.compilerOptions ??= {};
87	    const c = json.compilerOptions;
88	    c.paths ??= {};
89	
90	    if (c.paths[importPath]) {
91	      throw new Error(
92	        `You already have a library using the import path "${importPath}". Make sure to specify a unique one.`
93	      );
94	    }
95	
96	    c.paths[importPath] = lookupPaths.map(ensureRelativePath);
97	
98	    return json;
99	  });
100	}
