109	/**
110	 * When `baseUrl` is not set and `paths` are inherited via `extends`,
111	 * tools like `tsconfig-paths` resolve from the loaded file's directory
112	 * instead of the file where `paths` is defined. This walks the `extends`
113	 * chain to find the correct resolution base.
114	 *
115	 * Returns the directory that `paths` values should be resolved relative to.
116	 * Walks the tsconfig `extends` chain to find where `paths` is defined, then
117	 * looks for the applicable `baseUrl` from that point toward the root of the
118	 * chain (ignoring child overrides that don't apply to the paths-defining
119	 * tsconfig). When no `baseUrl` applies, returns the directory of the
120	 * tsconfig that defines `paths`.
121	 */
122	export function resolvePathsBaseUrl(tsconfigPath: string): string {
123	  const chain: { dir: string; raw: any }[] = [];
124	  const queue: string[] = [tsconfigPath];
125	  while (queue.length > 0) {
126	    const absolute = resolve(queue.shift()!);
127	    const dir = dirname(absolute);
128	    try {
129	      const raw = JSON.parse(readFileSync(absolute, 'utf-8'));
130	      chain.push({ dir, raw });
131	      const exts: string[] = raw.extends
