+{"version":3,"sources":["/workspace/repo/packages/devkit/src/generators/generate-files.ts"],"sourcesContent":["import { readdirSync, readFileSync, statSync } from 'fs';\nimport * as path from 'path';\nimport { isBinaryPath } from '../utils/binary-extensions';\n\nimport { logger, type Tree } from 'nx/src/devkit-exports';\n\n/**\n * Specify what should be done when a file is generated but already exists on the system\n */\nexport enum OverwriteStrategy {\n  Overwrite = 'overwrite',\n  KeepExisting = 'keepExisting',\n  ThrowIfExisting = 'throwIfExisting',\n}\n\n/**\n * Options for the generateFiles function\n */\nexport interface GenerateFilesOptions {\n  /**\n   * Specify what should be done when a file is generated but already exists on the system\n   */\n  overwriteStrategy?: OverwriteStrategy;\n}\n\n// TODO(v24): use the version from nx/src/generators/utils\n/**\n * Generates a folder of files based on provided templates.\n *\n * While doing so it performs two substitutions:\n * - Substitutes segments of file names surrounded by __\n * - Uses ejs to substitute values in templates\n *\n * Examples:\n * ```typescript\n * generateFiles(tree, path.join(__dirname , 'files'), './tools/scripts', {tmpl: '', name: 'myscript'})\n * ```\n * This command will take all the files from the `files` directory next to the place where the command is invoked from.\n * It will replace all `__tmpl__` with '' and all `__name__` with 'myscript' in the file names, and will replace all\n * `<%= name %>` with `myscript` in the files themselves.\n * `tmpl: ''` is a common pattern. With it you can name files like this: `index.ts__tmpl__`, so your editor\n * doesn't get confused about incorrect TypeScript files.\n *\n * @param tree - the file system tree\n * @param srcFolder - the source folder of files (absolute path)\n * @param target - the target folder (relative to the tree root)\n * @param substitutions - an object of key-value pairs\n * @param options - See {@link GenerateFilesOptions}\n */\nexport function generateFiles(\n  tree: Tree,\n  srcFolder: string,\n  target: string,\n  substitutions: { [k: string]: any },\n  options: GenerateFilesOptions = {\n    overwriteStrategy: OverwriteStrategy.Overwrite,\n  }\n): void {\n  options ??= {};\n  options.overwriteStrategy ??= OverwriteStrategy.Overwrite;\n\n  const ejs = require('ejs');\n\n  const files = allFilesInDir(srcFolder);\n  if (files.length === 0) {\n    throw new Error(\n      `generateFiles: No files found in \"${srcFolder}\". Are you sure you specified the correct path?`\n    );\n  } else {\n    files.forEach((filePath) => {\n      let newContent: Buffer | string;\n      const computedPath = computePath(\n        srcFolder,\n        target,\n        filePath,\n        substitutions\n      );\n\n      if (tree.exists(computedPath)) {\n        if (options.overwriteStrategy === OverwriteStrategy.KeepExisting) {\n          return;\n        } else if (\n          options.overwriteStrategy === OverwriteStrategy.ThrowIfExisting\n        ) {\n          throw new Error(\n            `Generated file already exists, not allowed by overwrite strategy in generator (${computedPath})`\n          );\n        }\n        // else: file should be overwritten, so just fall through to file generation\n      }\n\n      if (isBinaryPath(filePath)) {\n        newContent = readFileSync(filePath);\n      } else {\n        const template = readFileSync(filePath, 'utf-8');\n        try {\n          newContent = ejs.render(template, substitutions, {\n            filename: filePath,\n          });\n        } catch (e) {\n          logger.error(`Error in ${filePath.replace(`${tree.root}/`, '')}:`);\n          throw e;\n        }\n      }\n\n      tree.write(computedPath, newContent);\n    });\n  }\n}\n\nfunction computePath(\n  srcFolder: string,\n  target: string,\n  filePath: string,\n  substitutions: { [k: string]: any }\n): string {\n  const relativeFromSrcFolder = path.relative(srcFolder, filePath);\n  let computedPath = path.join(target, relativeFromSrcFolder);\n  if (computedPath.endsWith('.template')) {\n    computedPath = computedPath.substring(0, computedPath.length - 9);\n  }\n  Object.entries(substitutions).forEach(([propertyName, value]) => {\n    computedPath = computedPath.split(`__${propertyName}__`).join(value);\n  });\n  return computedPath;\n}\n\nfunction allFilesInDir(parent: string): string[] {\n  let res: string[] = [];\n  try {\n    readdirSync(parent).forEach((c) => {\n      const child = path.join(parent, c);\n      try {\n        const s = statSync(child);\n        if (!s.isDirectory()) {\n          res.push(child);\n        } else if (s.isDirectory()) {\n          res = [...res, ...allFilesInDir(child)];\n        }\n      } catch {}\n    });\n  } catch {}\n  return res;\n}\n"],"names":["OverwriteStrategy","generateFiles","tree","srcFolder","target","substitutions","options","overwriteStrategy","ejs","require","files","allFilesInDir","length","Error","forEach","filePath","newContent","computedPath","computePath","exists","isBinaryPath","readFileSync","template","render","filename","e","logger","error","replace","root","write","relativeFromSrcFolder","path","relative","join","endsWith","substring","Object","entries","propertyName","value","split","parent","res","readdirSync","c","child","s","statSync","isDirectory","push"],"mappings":";;;;oBAAoD;8DAC9B;kCACO;+BAEK;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;+BAKtBA;;;eAAAA;;;QAAAA;;;;+BAwCIC;;;eAAAA;;;QAAAA;;;;AAxCT,IAAA,AAAKD,2CAAAA;;;;WAAAA;;AAwCL,SAASC,cACdC,IAAU,EACVC,SAAiB,EACjBC,MAAc,EACdC,aAAmC,EACnCC,UAAgC;IAC9BC,iBAAiB;AACnB,CAAC;IAEDD,YAAY,CAAC;IACbA,QAAQC,iBAAiB;IAEzB,MAAMC,MAAMC,QAAQ;IAEpB,MAAMC,QAAQC,cAAcR;IAC5B,IAAIO,MAAME,MAAM,KAAK,GAAG;QACtB,MAAM,IAAIC,MACR,CAAC,kCAAkC,EAAEV,UAAU,+CAA+C,CAAC;IAEnG,OAAO;QACLO,MAAMI,OAAO,CAAC,CAACC;YACb,IAAIC;YACJ,MAAMC,eAAeC,YACnBf,WACAC,QACAW,UACAV;YAGF,IAAIH,KAAKiB,MAAM,CAACF,eAAe;gBAC7B,IAAIX,QAAQC,iBAAiB,qBAAqC;oBAChE;gBACF,OAAO,IACLD,QAAQC,iBAAiB,wBACzB;oBACA,MAAM,IAAIM,MACR,CAAC,+EAA+E,EAAEI,aAAa,CAAC,CAAC;gBAErG;YACA,4EAA4E;YAC9E;YAEA,IAAIG,IAAAA,8BAAY,EAACL,WAAW;gBAC1BC,aAAaK,IAAAA,gBAAY,EAACN;YAC5B,OAAO;gBACL,MAAMO,WAAWD,IAAAA,gBAAY,EAACN,UAAU;gBACxC,IAAI;oBACFC,aAAaR,IAAIe,MAAM,CAACD,UAAUjB,eAAe;wBAC/CmB,UAAUT;oBACZ;gBACF,EAAE,OAAOU,GAAG;oBACVC,qBAAM,CAACC,KAAK,CAAC,CAAC,SAAS,EAAEZ,SAASa,OAAO,CAAC,GAAG1B,KAAK2B,IAAI,CAAC,CAAC,CAAC,EAAE,IAAI,CAAC,CAAC;oBACjE,MAAMJ;gBACR;YACF;YAEAvB,KAAK4B,KAAK,CAACb,cAAcD;QAC3B;IACF;AACF;AAEA,SAASE,YACPf,SAAiB,EACjBC,MAAc,EACdW,QAAgB,EAChBV,aAAmC;IAEnC,MAAM0B,wBAAwBC,MAAKC,QAAQ,CAAC9B,WAAWY;IACvD,IAAIE,eAAee,MAAKE,IAAI,CAAC9B,QAAQ2B;IACrC,IAAId,aAAakB,QAAQ,CAAC,cAAc;QACtClB,eAAeA,aAAamB,SAAS,CAAC,GAAGnB,aAAaL,MAAM,GAAG;IACjE;IACAyB,OAAOC,OAAO,CAACjC,eAAeS,OAAO,CAAC,CAAC,CAACyB,cAAcC,MAAM;QAC1DvB,eAAeA,aAAawB,KAAK,CAAC,CAAC,EAAE,EAAEF,aAAa,EAAE,CAAC,EAAEL,IAAI,CAACM;IAChE;IACA,OAAOvB;AACT;AAEA,SAASN,cAAc+B,MAAc;IACnC,IAAIC,MAAgB,EAAE;IACtB,IAAI;QACFC,IAAAA,eAAW,EAACF,QAAQ5B,OAAO,CAAC,CAAC+B;YAC3B,MAAMC,QAAQd,MAAKE,IAAI,CAACQ,QAAQG;YAChC,IAAI;gBACF,MAAME,IAAIC,IAAAA,YAAQ,EAACF;gBACnB,IAAI,CAACC,EAAEE,WAAW,IAAI;oBACpBN,IAAIO,IAAI,CAACJ;gBACX,OAAO,IAAIC,EAAEE,WAAW,IAAI;oBAC1BN,MAAM;2BAAIA;2BAAQhC,cAAcmC;qBAAO;gBACzC;YACF,EAAE,OAAM,CAAC;QACX;IACF,EAAE,OAAM,CAAC;IACT,OAAOH;AACT"}
