{\n        './nx.json': JSON.stringify(nxJson),\n        './libs/my-lib/tsconfig.json': JSON.stringify({\n          compilerOptions: {\n            importHelpers: true,\n          },\n        }),\n        './libs/my-lib/.swcrc': JSON.stringify({\n          jsc: {\n            externalHelpers: true,\n          },\n        }),\n      },\n      '/root'\n    );\n    const libWithHelpers = {\n      name: 'my-lib',\n      type: 'lib' as const,\n      data: {\n        root: 'libs/my-lib',\n        targets: {\n          build1: {\n            executor: '@nx/js:tsc',\n            options: {\n              tsConfig: 'libs/my-lib/tsconfig.json',\n            },\n          },\n          build2: {\n            executor: '@nx/js:swc',\n            options: {},\n          },\n        },\n      },\n    };\n    const projectGraph = {\n      nodes: {\n        'my-lib': libWithHelpers,\n      },\n      externalNodes: {\n        'npm:tslib': {\n          name: 'npm:tslib' as const,\n          type: 'npm' as const,\n          data: {\n            packageName: 'tslib',\n            version: '2.6.0',\n          },\n        },\n        'npm:@swc/helpers': {\n          name: 'npm:@swc/helpers' as const,\n          type: 'npm' as const,\n          data: {\n            packageName: '@swc/helpers',\n            version: '0.5.0',\n          },\n        },\n      },\n      dependencies: {},\n    };\n    const projectFileMap = {\n      'my-lib': [],\n    };\n\n    expect(\n      findNpmDependencies(\n        '/root',\n        libWithHelpers,\n        projectGraph,\n        projectFileMap,\n        'build1'\n      )\n    ).toEqual({\n      tslib: '2.6.0',\n    });\n    expect(\n      findNpmDependencies(\n        '/root',\n        libWithHelpers,\n        projectGraph,\n        projectFileMap,\n        'build2'\n      )\n    ).toEqual({\n      '@swc/helpers': '0.5.0',\n    });\n  });\n\n  it.each`\n    fileName                | command\n    ${'tsconfig.base.json'} | ${'tsc --build tsconfig.lib.json --pretty --verbose'}\n    ${'tsconfig.json'}      | ${'tsc --build tsconfig.lib.json --pretty --verbose'}\n    ${'tsconfig.base.json'} | ${'tsgo --build tsconfig.lib.json'}\n    ${'tsconfig.json'}      | ${'tsgo --build tsconfig.lib.json'}\n  `(\n    'should pick up helper npm dependencies when using \"$command\" and run-commands',\n    ({ fileName, command }) => {\n      vol.fromJSON(\n        {\n          [`./${fileName}`]: JSON.stringify({\n            compilerOptions: { importHelpers: true },\n          }),\n          './nx.json': JSON.stringify(nxJson),\n          './libs/my-lib/tsconfig.json': JSON.stringify({\n            compilerOptions: {\n              importHelpers: true,\n            },\n          }),\n        },\n        '/root'\n      );\n      const lib = {\n        name: 'my-lib',\n        type: 'lib' as const,\n        data: {\n          root: 'libs/my-lib',\n          targets: {\n            build: {\n              executor: 'nx:run-commands',\n              options: {\n                command,\n              },\n            },\n          },\n        },\n      };\n      const projectGraph = {\n        nodes: {\n          'my-lib': lib,\n        },\n        externalNodes: {\n          'npm:tslib': {\n            name: 'npm:tslib' as const,\n            type: 'npm' as const,\n            data: {\n              packageName: 'tslib',\n              version: '2.6.0',\n            },\n          },\n        },\n        dependencies: {},\n      };\n      const projectFileMap = {\n        'my-lib': [],\n      };\n\n      expect(\n        findNpmDependencies('/root', lib, projectGraph, projectFileMap, 'build')\n      ).toEqual({\n        tslib: '2.6.0',\n      });\n    }\n  );\n\n  it('should handle missing ts/swc helper packages from externalNodes', () => {\n    vol.fromJSON(\n      {\n        './nx.json': JSON.stringify(nxJson),\n        './libs/my-lib/tsconfig.json': JSON.stringify({\n          compilerOptions: {\n            importHelpers: true,\n          },\n        }),\n        './libs/my-lib/.swcrc': JSON.stringify({\n          jsc: {\n            externalHelpers: true,\n          },\n        }),\n      },\n      '/root'\n    );\n    const libWithHelpers = {\n      name: 'my-lib',\n      type: 'lib' as const,\n      data: {\n        root: 'libs/my-lib',\n        targets: {\n          build1: {\n            executor: '@nx/js:tsc',\n            options: {\n              tsConfig: 'libs/my-lib/tsconfig.json',\n            },\n          },\n          build2: {\n            executor: '@nx/js:swc',\n            options: {},\n          },\n        },\n      },\n    };\n    const projectGraph = {\n      nodes: {\n        'my-lib': libWithHelpers,\n      },\n      externalNodes: {},\n      dependencies: {},\n    };\n    const projectFileMap = {\n      'my-lib': [],\n    };\n\n    expect(\n      findNpmDependencies(\n        '/root',\n        libWithHelpers,\n        projectGraph,\n        projectFileMap,\n        'build1'\n      )\n    ).toEqual({});\n    expect(\n      findNpmDependencies(\n        '/root',\n        libWithHelpers,\n        projectGraph,\n        projectFileMap,\n        'build2'\n      )\n    ).toEqual({});\n  });\n\n  it('should not pick up helper npm dependencies if not required', () => {\n    vol.fromJSON(\n      {\n        './libs/my-lib/tsconfig.json': JSON.stringify({\n          compilerOptions: {\n            importHelpers: false,\n          },\n        }),\n        './libs/my-lib/.swcrc': JSON.stringify({\n          jsc: {\n            externalHelpers: false,\n          },\n        }),\n      },\n      '/root'\n    );\n    const libWithInlinedHelpers = {\n      name: 'my-lib',\n      type: 'lib' as const,\n      data: {\n        root: 'libs/my-lib',\n        targets: {\n          build1: {\n            executor: '@nx/js:tsc',\n            options: {\n              tsConfig: 'libs/my-lib/tsconfig.json',\n            },\n          },\n          build2: {\n            executor: '@nx/js:swc',\n            options: {},\n          },\n        },\n      },\n    };\n    const projectGraph = {\n      nodes: {\n        'my-lib': libWithInlinedHelpers,\n      },\n      externalNodes: {\n        'npm:tslib': {\n          name: 'npm:tslib' as const,\n          type: 'npm' as const,\n          data: {\n            packageName: 'tslib',\n            version: '2.6.0',\n          },\n        },\n        'npm:@swc/helpers': {\n          name: 'npm:@swc/helpers' as const,\n          type: 'npm' as const,\n          data: {\n            packageName: '@swc/helpers',\n            version: '0.5.0',\n          },\n        },\n      },\n      dependencies: {},\n    };\n    const projectFileMap = {\n      'my-lib': [],\n    };\n\n    const results = findNpmDependencies(\n      '/root',\n      libWithInlinedHelpers,\n      projectGraph,\n      projectFileMap,\n      'build'\n    );\n\n    expect(results).toEqual({});\n  });\n\n  it('should pick up helper npm dependencies from runtimeHelpers', () => {\n    const libWithUnknownExecutor = {\n      name: 'my-lib',\n      type: 'lib' as const,\n      data: {\n        root: 'libs/my-lib',\n        targets: {\n          build: { executor: '@my-org/some-package:build' },\n        },\n      },\n    };\n    const projectGraph = {\n      nodes: {\n        'my-lib': libWithUnknownExecutor,\n      },\n      externalNodes: {\n        'npm:tslib': {\n          name: 'npm:tslib' as const,\n          type: 'npm' as const,\n          data: { packageName: 'tslib', version: '2.6.0' },\n        },\n        'npm:@swc/helpers': {\n          name: 'npm:@swc/helpers' as const,\n          type: 'npm' as const,\n          data: { packageName: '@swc/helpers', version: '0.5.0' },\n        },\n      },\n      dependencies: {},\n    };\n    const projectFileMap = { 'my-lib': [] };\n\n    const results = findNpmDependencies(\n      '/root',\n      libWithUnknownExecutor,\n      projectGraph,\n      projectFileMap,\n      'build',\n      { runtimeHelpers: ['tslib'] }\n    );\n\n    expect(results).toStrictEqual({ tslib: '2.6.0' });\n  });\n\n  it('should not duplicate helper npm dependencies when additionally set in runtimeHelpers', () => {\n    vol.fromJSON(\n      {\n        './nx.json': JSON.stringify(nxJson),\n        './libs/my-lib/tsconfig.json': JSON.stringify({\n          compilerOptions: { importHelpers: true },\n        }),\n      },\n      '/root'\n    );\n    const libWithUnknownExecutor = {\n      name: 'my-lib',\n      type: 'lib' as const,\n      data: {\n        root: 'libs/my-lib',\n        targets: {\n          build: {\n            executor: '@nx/js:tsc',\n            options: { tsConfig: 'libs/my-lib/tsconfig.json' },\n          },\n        },\n      },\n    };\n    const projectGraph = {\n      nodes: {\n        'my-lib': libWithUnknownExecutor,\n      },\n      externalNodes: {\n        'npm:tslib': {\n          name: 'npm:tslib' as const,\n          type: 'npm' as const,\n          data: { packageName: 'tslib', version: '2.6.0' },\n        },\n        'npm:@swc/helpers': {\n          name: 'npm:@swc/helpers' as const,\n          type: 'npm' as const,\n          data: { packageName: '@swc/helpers', version: '0.5.0' },\n        },\n      },\n      dependencies: {},\n    };\n    const projectFileMap = { 'my-lib': [] };\n\n    const results = findNpmDependencies(\n      '/root',\n      libWithUnknownExecutor,\n      projectGraph,\n      projectFileMap,\n      'build',\n      { runtimeHelpers: ['tslib'] }\n    );\n\n    expect(results).toStrictEqual({ tslib: '2.6.0' });\n  });\n\n  it('should support recursive collection of dependencies', () => {\n    vol.fromJSON(\n      {\n        './nx.json': JSON.stringify(nxJson),\n      },\n      '/root'\n    );\n    const parentLib = {\n      name: 'parent',\n      type: 'lib' as const,\n      data: {\n        root: 'libs/parent',\n        targets: { build: {} },\n      },\n    };\n    const projectGraph = {\n      nodes: {\n        parent: parentLib,\n        child1: {\n          name: 'child1',\n          type: 'lib' as const,\n          data: {\n            root: 'libs/child1',\n            targets: { build: {} },\n          },\n        },\n        child2: {\n          name: 'child2',\n          type: 'lib' as const,\n          data: {\n            root: 'libs/child2',\n            targets: { build: {} },\n          },\n        },\n      },\n      externalNodes: {\n        'npm:foo': {\n          name: 'npm:foo' as const,\n          type: 'npm' as const,\n          data: {\n            packageName: 'foo',\n            version: '1.0.0',\n          },\n        },\n      },\n      dependencies: {\n        parent: [\n          {\n            type: 'static',\n            source: 'parent',\n            target: 'child1',\n          },\n        ],\n        child1: [\n          {\n            type: 'static',\n            source: 'child1',\n            target: 'child2',\n          },\n        ],\n        child2: [\n          {\n            type: 'static',\n            source: 'child2',\n            target: 'npm:foo',\n          },\n        ],\n      },\n    };\n    const projectFileMap = {\n      parent: [{ file: 'libs/parent/index.ts', hash: '123', deps: ['child1'] }],\n      child1: [{ file: 'libs/child1/index.ts', hash: '123', deps: ['child2'] }],\n      child2: [\n        { file: 'libs/child2/index.ts', hash: '123', deps: ['npm:foo'] },\n      ],\n    };\n\n    const results = findNpmDependencies(\n      '/root',\n      parentLib,\n      projectGraph,\n      projectFileMap,\n      'build',\n      {\n        includeTransitiveDependencies: true,\n      }\n    );\n\n    expect(results).toEqual({\n      foo: '1.0.0',\n    });\n  });\n\n  it('should find workspace dependencies', () => {\n    vol.fromJSON(\n      {\n        './libs/lib3/package.json': JSON.stringify({\n          name: '@acme/lib3',\n          version: '0.0.1',\n        }),\n        './nx.json': JSON.stringify(nxJson),\n      },\n      '/root'\n    );\n    const lib1 = {\n      name: 'lib1',\n      type: 'lib' as const,\n      data: {\n        root: 'libs/lib1',\n        targets: { build: {} },\n      },\n    };\n    const lib2 = {\n      name: 'lib2',\n      type: 'lib' as const,\n      data: {\n        root: 'libs/lib2',\n        targets: { build: {} },\n      },\n    };\n    const lib3 = {\n      name: 'lib3',\n      type: 'lib' as const,\n      data: {\n        root: 'libs/lib3',\n        targets: { build: {} },\n      },\n    };\n    const projectGraph = {\n      nodes: {\n        lib1: lib1,\n        lib2: lib2,\n        lib3: lib3,\n      },\n      externalNodes: {},\n      dependencies: {},\n    };\n    const projectFileMap = {\n      lib1: [{ file: 'libs/lib1/index.ts', hash: '123', deps: ['lib3'] }],\n      lib2: [{ file: 'libs/lib1/index.ts', hash: '123', deps: ['lib3'] }],\n      lib3: [],\n    };\n\n    expect(\n      findNpmDependencies('/root', lib1, projectGraph, projectFileMap, 'build')\n    ).toEqual({\n      '@acme/lib3': '0.0.1',\n    });\n    expect(\n      findNpmDependencies('/root', lib2, projectGraph, projectFileMap, 'build')\n    ).toEqual({\n      '@acme/lib3': '0.0.1',\n    });\n  });\n\n  it('should support local path for workspace dependencies', () => {\n    vol.fromJSON(\n      {\n        './libs/c/package.json': JSON.stringify({\n          name: '@acme/c',\n          version: '0.0.1',\n        }),\n        './nx.json': JSON.stringify(nxJson),\n      },\n      '/root'\n    );\n    const a = {\n      name: 'a',\n      type: 'lib' as const,\n      data: {\n        root: 'libs/a',\n        targets: { build: {} },\n      },\n    };\n    const b = {\n      name: 'b',\n      type: 'lib' as const,\n      data: {\n        root: 'libs/b',\n        targets: { build: {} },\n      },\n    };\n    const c = {\n      name: 'c',\n      type: 'lib' as const,\n      data: {\n        root: 'libs/c',\n        targets: { build: {} },\n      },\n    };\n    const projectGraph = {\n      nodes: {\n        a: a,\n       