+{"version":3,"sources":["/workspace/repo/packages/nx/src/tasks-runner/task-graph-utils.ts"],"sourcesContent":["import { ProjectGraph } from '../config/project-graph';\nimport { Task, TaskGraph } from '../config/task-graph';\nimport { output } from '../utils/output';\n\nfunction _findCycle(\n  graph: {\n    dependencies: Record<string, string[]>;\n    continuousDependencies?: Record<string, string[]>;\n  },\n  id: string,\n  visited: { [taskId: string]: boolean },\n  path: string[]\n): string[] | null {\n  if (visited[id]) return null;\n  visited[id] = true;\n\n  for (const d of [\n    ...graph.dependencies[id],\n    ...(graph.continuousDependencies?.[id] ?? []),\n  ]) {\n    if (path.includes(d)) return [...path, d];\n    const cycle = _findCycle(graph, d, visited, [...path, d]);\n    if (cycle) return cycle;\n  }\n  return null;\n}\n\n/**\n * This function finds a cycle in the graph.\n * @returns the first cycle found, or null if no cycle is found.\n */\nexport function findCycle(graph: {\n  dependencies: Record<string, string[]>;\n  continuousDependencies?: Record<string, string[]>;\n}): string[] | null {\n  const visited = {};\n  for (const t of Object.keys(graph.dependencies)) {\n    visited[t] = false;\n  }\n\n  for (const t of Object.keys(graph.dependencies)) {\n    const cycle = _findCycle(graph, t, visited, [t]);\n    if (cycle) return cycle;\n  }\n\n  return null;\n}\n\n/**\n * This function finds all cycles in the graph.\n * @returns a list of unique task ids in all cycles found, or null if no cycle is found.\n */\nexport function findCycles(graph: {\n  dependencies: Record<string, string[]>;\n  continuousDependencies?: Record<string, string[]>;\n}): Set<string> | null {\n  const visited = {};\n  const cycles = new Set<string>();\n  for (const t of Object.keys(graph.dependencies)) {\n    visited[t] = false;\n  }\n\n  for (const t of Object.keys(graph.dependencies)) {\n    const cycle = _findCycle(graph, t, visited, [t]);\n    if (cycle) {\n      cycle.forEach((t) => cycles.add(t));\n    }\n  }\n\n  return cycles.size ? cycles : null;\n}\n\nfunction _makeAcyclic(\n  graph: {\n    dependencies: Record<string, string[]>;\n    continuousDependencies?: Record<string, string[]>;\n  },\n  id: string,\n  visited: { [taskId: string]: boolean },\n  path: string[]\n) {\n  if (visited[id]) return;\n  visited[id] = true;\n\n  const deps = graph.dependencies[id];\n  const continuousDeps = graph.continuousDependencies?.[id] ?? [];\n  for (const d of [...deps, ...continuousDeps]) {\n    if (path.includes(d)) {\n      const depsIdx = deps.indexOf(d);\n      if (depsIdx >= 0) {\n        deps.splice(depsIdx, 1);\n      }\n      const continuousIdx = continuousDeps.indexOf(d);\n      if (continuousIdx >= 0) {\n        continuousDeps.splice(continuousIdx, 1);\n      }\n    } else {\n      _makeAcyclic(graph, d, visited, [...path, d]);\n    }\n  }\n  return null;\n}\n\nexport function makeAcyclic(graph: {\n  roots: string[];\n  dependencies: Record<string, string[]>;\n}): void {\n  const visited = {};\n  for (const t of Object.keys(graph.dependencies)) {\n    visited[t] = false;\n  }\n  for (const t of Object.keys(graph.dependencies)) {\n    _makeAcyclic(graph, t, visited, [t]);\n  }\n  graph.roots = Object.keys(graph.dependencies).filter(\n    (t) => graph.dependencies[t].length === 0\n  );\n}\n\nexport function validateNoAtomizedTasks(\n  taskGraph: TaskGraph,\n  projectGraph: ProjectGraph\n) {\n  const getNonAtomizedTargetForTask = (task) =>\n    projectGraph.nodes[task.target.project]?.data?.targets?.[task.target.target]\n      ?.metadata?.nonAtomizedTarget;\n\n  const atomizedRootTasks = Object.values(taskGraph.tasks).filter(\n    (task) => getNonAtomizedTargetForTask(task) !== undefined\n  );\n\n  if (atomizedRootTasks.length === 0) {\n    return;\n  }\n\n  const nonAtomizedTasks = atomizedRootTasks\n    .map((t) => `\"${getNonAtomizedTargetForTask(t)}\"`)\n    .filter((item, index, arr) => arr.indexOf(item) === index);\n\n  const moreInfoLines = [\n    `Please enable Nx Cloud or use the slower ${nonAtomizedTasks.join(\n      ','\n    )} task${nonAtomizedTasks.length > 1 ? 's' : ''}.`,\n    'Learn more at https://nx.dev/ci/features/split-e2e-tasks#nx-cloud-is-required-to-run-atomized-tasks',\n  ];\n\n  if (atomizedRootTasks.length === 1) {\n    output.error({\n      title: `The ${atomizedRootTasks[0].id} task should only be run with Nx Cloud.`,\n      bodyLines: [...moreInfoLines],\n    });\n  } else {\n    output.error({\n      title: `The following tasks should only be run with Nx Cloud:`,\n      bodyLines: [\n        ...atomizedRootTasks.map((task) => `  - ${task.id}`),\n        '',\n        ...moreInfoLines,\n      ],\n    });\n  }\n  process.exit(1);\n}\n\nexport function assertTaskGraphDoesNotContainInvalidTargets(\n  taskGraph: TaskGraph\n) {\n  const nonParallelTasksThatDependOnContinuousTasks = [];\n  const nonParallelContinuousTasksThatAreDependedOn = [];\n  for (const task of Object.values(taskGraph.tasks)) {\n    if (\n      task.parallelism === false &&\n      taskGraph.continuousDependencies[task.id].length > 0\n    ) {\n      nonParallelTasksThatDependOnContinuousTasks.push(task);\n    }\n    for (const dependency of taskGraph.continuousDependencies[task.id]) {\n      if (taskGraph.tasks[dependency].parallelism === false) {\n        nonParallelContinuousTasksThatAreDependedOn.push(\n          taskGraph.tasks[dependency]\n        );\n      }\n    }\n  }\n\n  if (nonParallelTasksThatDependOnContinuousTasks.length > 0) {\n    throw new NonParallelTaskDependsOnContinuousTasksError(\n      nonParallelTasksThatDependOnContinuousTasks,\n      taskGraph\n    );\n  }\n  if (nonParallelContinuousTasksThatAreDependedOn.length > 0) {\n    throw new DependingOnNonParallelContinuousTaskError(\n      nonParallelContinuousTasksThatAreDependedOn,\n      taskGraph\n    );\n  }\n}\n\nclass NonParallelTaskDependsOnContinuousTasksError extends Error {\n  constructor(\n    public invalidTasks: Task[],\n    taskGraph: TaskGraph\n  ) {\n    let message =\n      'The following tasks do not support parallelism but depend on continuous tasks:';\n\n    for (const task of invalidTasks) {\n      message += `\\n - ${task.id} -> ${taskGraph.continuousDependencies[\n        task.id\n      ].join(', ')}`;\n    }\n\n    super(message);\n    this.name = 'NonParallelTaskDependsOnContinuousTasksError';\n  }\n}\n\nclass DependingOnNonParallelContinuousTaskError extends Error {\n  constructor(\n    public invalidTasks: Task[],\n    taskGraph: TaskGraph\n  ) {\n    let message =\n      'The following continuous tasks do not support parallelism but are depended on:';\n\n    for (const task of invalidTasks) {\n      const dependents = Object.keys(taskGraph.continuousDependencies).filter(\n        (parentTaskId) =>\n          taskGraph.continuousDependencies[parentTaskId].includes(task.id)\n      );\n\n      message += `\\n - ${task.id} <- ${dependents.join(', ')}`;\n    }\n\n    message +=\n      '\\nParallelism must be enabled for a continuous task if it is depended on, as the tasks that depend on it will run in parallel with it.';\n\n    super(message);\n    this.name = 'DependingOnNonParallelContinuousTaskError';\n  }\n}\n\nexport function getLeafTasks(taskGraph: TaskGraph): Set<string> {\n  const reversed = reverseTaskGraph(taskGraph);\n  const leafTasks = new Set<string>();\n  for (const [taskId, dependencies] of Object.entries(reversed.dependencies)) {\n    if (dependencies.length === 0) {\n      leafTasks.add(taskId);\n    }\n  }\n\n  return leafTasks;\n}\n\nfunction reverseTaskGraph(taskGraph: TaskGraph): TaskGraph {\n  const reversed = {\n    tasks: taskGraph.tasks,\n    dependencies: Object.fromEntries(\n      Object.entries(taskGraph.tasks).map(([taskId]) => [taskId, []])\n    ),\n  } as TaskGraph;\n  for (const [taskId, dependencies] of Object.entries(taskGraph.dependencies)) {\n    for (const dependency of dependencies) {\n      reversed.dependencies[dependency].push(taskId);\n    }\n  }\n  for (const [taskId, dependencies] of Object.entries(\n    taskGraph.continuousDependencies\n  )) {\n    for (const dependency of dependencies) {\n      reversed.dependencies[dependency].push(taskId);\n    }\n  }\n  return reversed;\n}\n\n/**\n * Walk a task graph topologically, calling walkFn for each wave of roots.\n * Considers both dependencies and continuousDependencies.\n */\nexport async function walkTaskGraph(\n  taskGraph: TaskGraph,\n  walkFn: (rootTaskIds: string[]) => Promise<void>\n): Promise<void> {\n  const reversed = reverseTaskGraph(taskGraph);\n  const inDegree: Record<string, number> = {};\n  for (const id of Object.keys(taskGraph.tasks)) {\n    inDegree[id] =\n      (taskGraph.dependencies[id]?.length ?? 0) +\n      (taskGraph.continuousDependencies?.[id]?.length ?? 0);\n  }\n\n  let currentRoots = taskGraph.roots.slice();\n\n  while (currentRoots.length > 0) {\n    await walkFn(currentRoots);\n\n    const nextRoots: string[] = [];\n    for (const id of currentRoots) {\n      for (const depId of reversed.dependencies[id] ?? []) {\n        inDegree[depId]--;\n        if (inDegree[depId] === 0) {\n          nextRoots.push(depId);\n        }\n      }\n    }\n    currentRoots = nextRoots;\n  }\n}\n"],"names":["assertTaskGraphDoesNotContainInvalidTargets","findCycle","findCycles","getLeafTasks","makeAcyclic","validateNoAtomizedTasks","walkTaskGraph","_findCycle","graph","id","visited","path","d","dependencies","continuousDependencies","includes","cycle","t","Object","keys","cycles","Set","forEach","add","size","_makeAcyclic","deps","continuousDeps","depsIdx","indexOf","splice","continuousIdx","roots","filter","length","taskGraph","projectGraph","getNonAtomizedTargetForTask","task","nodes","target","project","data","targets","metadata","nonAtomizedTarget","atomizedRootTasks","values","tasks","undefined","nonAtomizedTasks","map","item","index","arr","moreInfoLines","join","output","error","title","bodyLines","process","exit","nonParallelTasksThatDependOnContinuousTasks","nonParallelContinuousTasksThatAreDependedOn","parallelism","push","dependency","NonParallelTaskDependsOnContinuousTasksError","DependingOnNonParallelContinuousTaskError","Error","invalidTasks","message","name","dependents","parentTaskId","reversed","reverseTaskGraph","leafTasks","taskId","entries","fromEntries","walkFn","inDegree","currentRoots","slice","nextRoots","depId"],"mappings":";;;;wBAEuB;+BAkKPA;;;eAAAA;;;QAAAA;;;;+BArIAC;;;eAAAA;;;QAAAA;;;;+BAqBAC;;;eAAAA;;;QAAAA;;;;+BA+LAC;;;eAAAA;;;QAAAA;;;;+BA5IAC;;;eAAAA;;;QAAAA;;;;+BAgBAC;;;eAAAA;;;QAAAA;;;;+BAkKMC;;;eAAAA;;;QAAAA;;;;AArRtB,SAASC,WACPC,KAGC,EACDC,EAAU,EACVC,OAAsC,EACtCC,IAAc;IAEd,IAAID,OAAO,CAACD,GAAG,EAAE,OAAO;IACxBC,OAAO,CAACD,GAAG,GAAG;IAEd,KAAK,MAAMG,KAAK;WACXJ,MAAMK,YAAY,CAACJ,GAAG;WACrBD,MAAMM,sBAAsB,EAAE,CAACL,GAAG,IAAI,EAAE;KAC7C,CAAE;QACD,IAAIE,KAAKI,QAAQ,CAACH,IAAI,OAAO;eAAID;YAAMC;SAAE;QACzC,MAAMI,QAAQT,WAAWC,OAAOI,GAAGF,SAAS;eAAIC;YAAMC;SAAE;QACxD,IAAII,OAAO,OAAOA;IACpB;IACA,OAAO;AACT;AAMO,SAASf,UAAUO,KAGzB;IACC,MAAME,UAAU,CAAC;IACjB,KAAK,MAAMO,KAAKC,OAAOC,IAAI,CAACX,MAAMK,YAAY,EAAG;QAC/CH,OAAO,CAACO,EAAE,GAAG;IACf;IAEA,KAAK,MAAMA,KAAKC,OAAOC,IAAI,CAACX,MAAMK,YAAY,EAAG;QAC/C,MAAMG,QAAQT,WAAWC,OAAOS,GAAGP,SAAS;YAACO;SAAE;QAC/C,IAAID,OAAO,OAAOA;IACpB;IAEA,OAAO;AACT;AAMO,SAASd,WAAWM,KAG1B;IACC,MAAME,UAAU,CAAC;IACjB,MAAMU,SAAS,IAAIC;IACnB,KAAK,MAAMJ,KAAKC,OAAOC,IAAI,CAACX,MAAMK,YAAY,EAAG;QAC/CH,OAAO,CAACO,EAAE,GAAG;IACf;IAEA,KAAK,MAAMA,KAAKC,OAAOC,IAAI,CAACX,MAAMK,YAAY,EAAG;QAC/C,MAAMG,QAAQT,WAAWC,OAAOS,GAAGP,SAAS;YAACO;SAAE;QAC/C,IAAID,OAAO;YACTA,MAAMM,OAAO,CAAC,CAACL,IAAMG,OAAOG,GAAG,CAACN;QAClC;IACF;IAEA,OAAOG,OAAOI,IAAI,GAAGJ,SAAS;AAChC;AAEA,SAASK,aACPjB,KAGC,EACDC,EAAU,EACVC,OAAsC,EACtCC,IAAc;IAEd,IAAID,OAAO,CAACD,GAAG,EAAE;IACjBC,OAAO,CAACD,GAAG,GAAG;IAEd,MAAMiB,OAAOlB,MAAMK,YAAY,CAACJ,GAAG;IACnC,MAAMkB,iBAAiBnB,MAAMM,sBAAsB,EAAE,CAACL,GAAG,IAAI,EAAE;IAC/D,KAAK,MAAMG,KAAK;WAAIc;WAASC;KAAe,CAAE;QAC5C,IAAIhB,KAAKI,QAAQ,CAACH,IAAI;YACpB,MAAMgB,UAAUF